// A recoverable checkpoint, never a second active state database.
export function indexedRecovery(indexed=globalThis.indexedDB){let dbPromise;function open(){return dbPromise??=new Promise((resolve,reject)=>{if(!indexed)return reject(new Error('IndexedDB不可用'));const request=indexed.open('qinghe-arg-recovery',1);request.onupgradeneeded=()=>request.result.createObjectStore('checkpoint');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(new Error('恢复库暂被旧页面占用'));});}return {async get(){const db=await open();return new Promise((resolve,reject)=>{const r=db.transaction('checkpoint').objectStore('checkpoint').get('v4');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});},async set(value){const db=await open();return new Promise((resolve,reject)=>{const t=db.transaction('checkpoint','readwrite');t.objectStore('checkpoint').put(value,'v4');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||new Error('恢复事务未提交'));});},async close(){try{(await dbPromise)?.close();}catch{}}};}
